// /frontend-react/src/components/Dashboard.js (FINALIZED SYMMETRICAL CODE)

import React from 'react';

// --- DashboardHeader: Simplified Menu Icon ---
const DashboardHeader = ({ onMenuClick, isEasyMode }) => (
    <div style={{ 
        display: 'flex', 
        justifyContent: 'flex-end', 
        padding: '15px 20px', 
        backgroundColor: 'transparent', 
        position: 'absolute', 
        top: 0,
        right: 0,
        width: '100%',
        zIndex: 15, // Ensures the menu icon is tappable over the notification
    }}>
        <button
            onClick={onMenuClick}
            style={{
                padding: '8px',
                backgroundColor: 'transparent', 
                border: 'none', 
                borderRadius: '0', 
                cursor: 'pointer',
                fontSize: isEasyMode ? '36px' : '28px', 
                color: '#333',
                transition: 'color 0.2s',
            }}
            onMouseOver={e => e.currentTarget.style.color = '#1A73E8'} 
            onMouseOut={e => e.currentTarget.style.color = '#333'}
        >
            <span role="img" aria-label="Menu">☰</span>
        </button>
    </div>
);
// --- END DashboardHeader ---


const Icon = ({ name, emoji, isActive, onClick, isEasyMode }) => (
    <div 
        // Only the active medical icon is clickable for navigation
        onClick={isActive ? onClick : () => isEasyMode && console.log(`Audio: '${name} - Not Available Yet' - Muted Icon`)}
        style={{
            padding: '25px', 
            margin: '15px',
            border: `5px solid ${isActive ? '#1A73E8' : '#e0e0e0'}`, // Blue border for active
            borderRadius: '15px', 
            width: '40%',
            textAlign: 'center',
            backgroundColor: isActive ? '#E8F0FE' : '#ffffff', // Light background for active
            filter: isActive ? 'none' : 'grayscale(80%)', // Muted appearance for inactive
            opacity: isActive ? 1 : 0.7, 
            cursor: isActive ? 'pointer' : 'default',
            boxShadow: isActive ? '0 8px 15px rgba(0, 0, 0, 0.3)' : '0 2px 5px rgba(0, 0, 0, 0.1)', 
            transition: 'all 0.3s',
            fontSize: isEasyMode ? '36px' : '20px',
        }}
    >
        <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
        <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
    </div>
);

function Dashboard({ isEasyMode, goToMedical, onMenuClick }) { 
    
    const showAppointmentNotification = true; 

    const handleNotificationClick = () => {
        console.log("Notification clicked. Redirecting to Appointment Flow.");
        goToMedical(); 
    };
    
    // --- REVISED NOTIFICATION STYLE (Floating Card) ---
    const notificationStyle = {
        padding: '15px 25px', 
        margin: '15px', 
        backgroundColor: '#FFF3CD', 
        color: '#856404', 
        textAlign: 'center',
        cursor: 'pointer',
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderRadius: '10px',
        borderLeft: '5px solid #FFC107', 
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        position: 'relative', 
        zIndex: 10,
    };


    return (
        <div style={{ position: 'relative' }}>
            {/* RENDER THE MENU ICON AT THE TOP RIGHT (z-index 15) */}
            <DashboardHeader onMenuClick={onMenuClick} isEasyMode={isEasyMode} />

            {/* RENDER THE NOTIFICATION BANNER */}
            {showAppointmentNotification && (
                <div 
                    onClick={handleNotificationClick}
                    style={notificationStyle}
                >
                    <span role="img" aria-label="Alert" style={{marginRight: '10px'}}>🔔</span>
                    APPOINTMENT SOON! Tap Here.
                </div>
            )}

            {/* MAIN ICON GRID - FINAL SYMMETRICAL 2X2 ALIGNMENT */}
            <div style={{ 
                display: 'flex', 
                flexWrap: 'wrap', 
                justifyContent: 'center', 
                paddingTop: showAppointmentNotification ? '20px' : '40px', 
                paddingBottom: '40px' 
            }}>
                {/* Row 1 */}
                <Icon name="Medical Access" emoji="🏥" isActive={true} onClick={goToMedical} isEasyMode={isEasyMode}/>
                <Icon name="Emergency Info" emoji="🆘" isActive={false} isEasyMode={isEasyMode}/>
                
                {/* Row 2 */}
                <Icon name="Medical History" emoji="📜" isActive={false} isEasyMode={isEasyMode}/>
                
                {/* HIDDEN SPACER ICON: Forces Medical History to the left and maintains the 2x2 centered structure */}
                <div style={{ width: '40%', margin: '15px', visibility: 'hidden' }}></div>
            </div>
        </div>
    );
}

export default Dashboard;
